WFJ.Data.add("book", {
  ["9710c91691bc151a"] = { "Il giovane orco divenne un avido studioso della magia demoniaca e diventò lo stregone mortale più potente della storia. Insegnò le arti arcane ad altri giovani orchi e si adoperò per estirpare le tradizioni sciamaniche degli orchi. Gul'dan mostrò ai suoi fratelli un nuovo genere di magia, un nuovo e terribile potere che sapeva di rovina.", "." },
  ["972dead9975f01b8"] = { "Il suo orgoglio era completamente distrutto. Per la seconda volta nella sua esistenza, Staghelm avrebbe sentito quel tremito alla bocca dello stomaco che solo la paura può provocare. Fu dunque a Tanaris che Staghelm si presentò ad Anachronos, progenie di Nozdormu, per implorare l'aiuto dello Stormo dei Draghi di Bronzo.", "." },
  ["9741a73a6e0df187"] = { "La regina Azshara, sopraffatta dalla terribile estasi della sua magia, cadde vittima dell'innegabile potere di Sargeras e accettò di concedergli l'accesso al suo mondo. Persino i suoi servitori ⟦Highborne=Alti Nobili⟧ si abbandonarono all'inevitabile corruzione della magia e cominciarono ad adorare Sargeras come loro dio. Per dimostrare la loro fedeltà alla Legione, gli ⟦Highborne=Alti Nobili⟧ aiutarono la loro regina ad aprire un vasto portale vorticante nelle profondità del ⟦Well of Eternity=Pozzo dell'Eternità⟧.", "." },
  ["9742154e9863aad9"] = { "Senza più un posto dove andare, Kael e i suoi elfi del sangue seguirono Lady Vashj nelle ⟦Outland=Terre Esterne⟧ per contrastare la sorvegliante Maiev, che aveva catturato di nuovo Illidan. Unendo le forze dei naga e degli elfi del sangue, riuscirono a sconfiggere Maiev e a liberare Illidan dalla sua stretta. Dalla sua base nelle ⟦Outland=Terre Esterne⟧, Illidan radunò le sue forze per un secondo attacco contro il Re dei Lich e la sua fortezza della Corona di Ghiaccio.", "." },
  ["9752018048f15b44"] = { "Le informazioni che ho appreso sugli Aspetti le riporto qui, perché altri possano consultarle in futuro. So che si riveleranno utili, perché sento che questi draghi avranno un effetto molto più grande sul nostro mondo con il passare del tempo.", "." },
  ["97dd5f8312dcbfca"] = { "Una Luna splende sulla Valle\nE posa il suo chiarore sulla giungla\nDove fieri Guerrieri rispondono alla chiamata\nA difesa della nostra Nazione e delle terre sacre.\n\nUna Luna splende sulla Valle\nBen sopra le grida della battaglia\nDove scorre il sangue\nDi nemici e compagni insieme.", "." },
})
